Tool response:
Tool: update_order
Description: Update an existing order to convert it to a limit order with modified parameters.
Parameters:
    {
      "type": "object",
      "properties": {
        "order_id": {
          "type": "integer",
          "minimum": 1,
          "title": "Order Id",
          "description": ""
        },
        "limit_price": {
          "type": "number",
          "title": "Limit Price",
          "description": "New limit price for the order"
        },
        "time_in_force": {
          "type": "string",
          "title": "Time In Force",
          "description": "Time in force for the order (must be 'gtc')"
        }
      },
      "required": [
        "order_id",
        "limit_price",
        "time_in_force"
      ]
    }

